/**
 * 生成一个最小的单页 PDF（用于 pdf.js 本地渲染验证），输出到 resources/sample.pdf。
 * 不依赖第三方库，手写合法 xref/trailer。
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const outDir = path.join(root, 'resources')
fs.mkdirSync(outDir, { recursive: true })

const lines = [
  'Jiu Ying Heng Feng - Replica',
  'PDF local rendering sample',
  '',
  'This file is generated by scripts/make-sample-pdf.mjs.',
  'It verifies pdfjs-dist local rendering in the replica app.',
  'Original app: preview-pdf chunk + main-process openPDF IPC.'
]
const text = lines.map((line, i) => `BT /F1 16 Tf 72 ${760 - i * 26} Td (${line.replace(/[()\\]/g, '')}) Tj ET`).join('\n')

const objects = []
objects.push('<< /Type /Catalog /Pages 2 0 R >>')
objects.push('<< /Type /Pages /Kids [3 0 R] /Count 1 >>')
objects.push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>')
objects.push(`<< /Length ${Buffer.byteLength(text, 'latin1')} >>\nstream\n${text}\nendstream`)
objects.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')

let pdf = '%PDF-1.4\n'
const offsets = [0]
objects.forEach((body, index) => {
  offsets.push(Buffer.byteLength(pdf, 'latin1'))
  pdf += `${index + 1} 0 obj\n${body}\nendobj\n`
})
const xrefOffset = Buffer.byteLength(pdf, 'latin1')
pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`
for (let i = 1; i <= objects.length; i++) pdf += String(offsets[i]).padStart(10, '0') + ' 00000 n \n'
pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`

const target = path.join(outDir, 'sample.pdf')
fs.writeFileSync(target, Buffer.from(pdf, 'latin1'))
console.log('[sample-pdf] wrote', target, fs.statSync(target).size, 'bytes')
